#!/usr/bin/env python3
"""Generate the 16x16 pixel font atlas (RGBA PNG) for Phase 35.

Deterministic: the glyph table is static data in this file, so the output
is stable across runs and platforms. Re-run after editing this file to
refresh assets/textures/font.png.

Atlas layout (256x512, 32px cells; 16 rows so that ASCII codes 32..126
keep the old c // 8 row indexing):
  - cells are indexed by ASCII code: cell (c % 8, c // 8);
  - each 16x16 glyph is drawn centered in its 32px cell (8px offset);
  - ink pixels are white with full alpha; everything else is transparent.

Glyph data: the FONT table below was extracted once (offline) from
DejaVu Sans Bold, em 16px, baseline at cell row 12 (descenders use rows
13..15), coverage threshold 128. The table is static: the game build
never needs the TTF. 2 px strokes, monospace (the advance is the full
16 px cell, see src/ui/font.cpp).

The game (src/ui/font.cpp) maps a character to its cell and reads the
16x16 sub-rect; unknown characters fall back to the '?' glyph.
"""
import os
import struct
import zlib

W, H = 256, 512
CELL = 32
OUT = os.path.join(os.path.dirname(__file__), "..", "assets",
                   "textures", "font.png")


def chunk(tag: bytes, data: bytes) -> bytes:
    c = struct.pack(">I", len(data)) + tag + data
    c += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    return c


def write_png(path: str, pixels) -> None:
    """pixels: list of rows, each a list of (r, g, b, a) tuples."""
    sig = b"\x89PNG\r\n\x1a\n"
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 6, 0, 0, 0)
    raw = bytearray()
    for row in pixels:
        raw.append(0)  # filter: None
        for (r, g, b, a) in row:
            raw += bytes((r, g, b, a))
    out = (sig + chunk(b"IHDR", ihdr)
           + chunk(b"IDAT", zlib.compress(bytes(raw)))
           + chunk(b"IEND", b""))
    with open(path, "wb") as f:
        f.write(out)


